                {`// writing/content/Chapter.tsx
import { Section } from './Section';
import { Title } from './Title';

export class Chapter extends Section {
  number?: number;
  title?: Title;
  
  renderHeader(): React.ReactNode {
    if (!this.title) return null;
    
    // Get the book from container hierarchy
    const book = this.findAncestor('Book');
    
    if (book) {
      // Title is a link back to the book
      return (
        <h1 className="chapter-title">
          <a href={\`#\${book.id}\`}>
            {this.number && \`Chapter \${this.number}: \`}
            {this.title.text()}
          </a>
        </h1>
      );
    }
    
    return (
      <h1 className="chapter-title">
        {this.number && \`Chapter \${this.number}: \`}
        {this.title?.text()}
      </h1>
    );
  }
  
  findAncestor(className: string): Work | null {
    let current = this.container;
    while (current) {
      if (current.constructor.name === className) {
        return current;
      }
      current = current.container;
    }
    return null;
  }
  
  renderContent(): React.ReactNode {
    return (
      <>
        {this.renderHeader()}
        {super.renderContent()}
      </>
    );
  }
}`}
