                {`// writing/interactive/Rose.tsx - IMPROVED with styled-components
import { Work } from '../../base/Work';
import { Author } from '../references/Author';
import styled from 'styled-components';

const imageVersion = process.env.NEXT_PUBLIC_DNA_ROSE_IMAGE_VERSION || 'v1';

const RightAlignedRose = styled.img<{ offsetX: string; offsetY: string }>\`
  position: absolute;
  top: calc(50% + \${(props) => props.offsetY});
  right: \${(props) => \`calc(\${props.offsetX} - 12.5px)\`};
  width: 25px;
  height: 25px;
  cursor: pointer;
  transition: transform 0.4s ease-in-out;
  transform-origin: center;
  transform: translate(50%, -50%);

  &:hover {
    transform: translate(50%, -50%) scale(1.1);
  }
\`;

const LeftAlignedRose = styled.img<{ padding: string; offsetY: string }>\`
  display: inline-block;
  vertical-align: middle;
  width: 25px;
  height: 25px;
  margin-right: \${(props) => props.padding};
  margin-top: \${(props) => props.offsetY};
  cursor: pointer;
  transition: transform 0.4s ease-in-out;

  &:hover {
    transform: scale(1.1);
  }
\`;

const InlineRose = styled.img\`
  display: inline-block;
  vertical-align: middle;
  width: 20px;
  height: 20px;
  margin: 0 4px;
  cursor: pointer;
  transition: transform 0.3s ease;

  &:hover {
    transform: scale(1.2);
  }
\`;

export class Rose extends Work {
  alignment: 'left' | 'right' | 'inline' = 'inline';
  target: string = 'https://dna.love';
  from?: Author;
  hovered: boolean = false;
  offsetX: string = '0px';
  offsetY: string = '0px';
  padding: string = '0px';
  
  getSrc(): string {
    return this.hovered
      ? \`/images/icons/dna-rose-g1-fill-10-icon.png?\${imageVersion}\`
      : \`/images/icons/dna-rose-g1-icon.png?\${imageVersion}\`;
  }
  
  component(): React.ReactNode {
    const props = {
      src: this.getSrc(),
      alt: "DNA Rose",
      onClick: () => window.location.href = this.target,
      onMouseEnter: () => this.hovered = true,
      onMouseLeave: () => this.hovered = false
    };
    
    if (this.alignment === 'right') {
      return (
        <RightAlignedRose
          {...props}
          offsetX={this.offsetX}
          offsetY={this.offsetY}
        />
      );
    }
    
    if (this.alignment === 'left') {
      return (
        <LeftAlignedRose
          {...props}
          offsetY={this.offsetY}
          padding={this.padding}
        />
      );
    }
    
    return <InlineRose {...props} />;
  }
}`}
