                {`${''}// base/Breadcrumbs.tsx - NEW FILE
import { Chemical } from '@/chemistry';
import { Work } from './Work';
import { Link } from '../writing/references/Link';
import styled from 'styled-components';

const BreadcrumbContainer = styled.div\`
  display: flex;
  align-items: center;
  font-size: 14px;
  color: var(--text-color, #666);
  
  > span {
    margin: 0 8px;
    color: #999;
  }
\`;

export class Breadcrumbs extends Chemical {
  work?: Work;
  
  getPath(): Work[] {
    const path: Work[] = [];
    let current = this.work;
    
    while (current) {
      path.unshift(current);
      current = current.container;
    }
    
    return path;
  }
  
  component(): React.ReactNode {
    const path = this.getPath();
    
    return (
      <BreadcrumbContainer>
        {path.map((work, i) => (
          <React.Fragment key={work.id || i}>
            {i > 0 && <span>›</span>}
            <Link target={work} text={this.getLabel(work)} />
          </React.Fragment>
        ))}
      </BreadcrumbContainer>
    );
  }
  
  getLabel(work: Work): string {
    // Get appropriate label based on work type
    if ('title' in work && work.title) {
      return work.title.text();
    }
    if ('name' in work && work.name) {
      return work.name;
    }
    return work.constructor.name;
  }
}`}
