                {`${''}import { Chapter } from '../../content/Chapter';
import { Writing } from '../../Writing';

export class TitlePage extends Chapter {
  additionalContent: Writing[] = [];
  
  processChildren(children: React.ReactNode): void {
    super.processChildren(children);
    // Collect any Writing children for bottom of page
    if (!children) return;
    const items = Array.isArray(children) ? children : [children];
    items.forEach((child: any) => {
      if (child instanceof Writing && 
          !(child instanceof Title) && 
          !(child instanceof Author)) {
        this.additionalContent.push(child);
      }
    });
  }
  
  titlePageStyles(): React.CSSProperties {
    return {
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'center',
      background: '#ffffff',
      padding: '40px'
    };
  }
  
  titleStyles(): React.CSSProperties {
    return {
      fontSize: '4em',
      color: '#000000',
      textAlign: 'center',
      marginBottom: '30px',
      fontFamily: 'Merriweather, serif',
      fontWeight: 300
    };
  }
  
  authorStyles(): React.CSSProperties {
    return {
      fontSize: '1.5em',
      color: '#333333',
      fontStyle: 'italic',
      marginBottom: '60px'
    };
  }
  
  additionalStyles(): React.CSSProperties {
    return {
      position: 'absolute',
      bottom: '60px',
      textAlign: 'center',
      color: '#666666'
    };
  }
  
  component(): React.ReactNode {
    const book = this.container as Book;
    const next = this.findNextChapter();
    
    return (
      <div style={this.titlePageStyles()}>
        <h1 style={this.titleStyles()}>
          {book?.title?.text()}
        </h1>
        <div style={this.authorStyles()}>
          {book?.author?.displayName}
        </div>
        
        {this.additionalContent.length > 0 && (
          <div style={this.additionalStyles()}>
            {this.additionalContent.map((content, i) => (
              <div key={i}>{content.component()}</div>
            ))}
          </div>
        )}
        
        {next && (
          <div style={{ position: 'absolute', bottom: '20px', right: '20px' }}>
            <Next target={next} />
          </div>
        )}
      </div>
    );
  }
}

const titlePage = new TitlePage();
export default titlePage.render();`}
