                {`${''}import { Work } from '../../../base/Work';
import { Title } from '../../content/Title';
import { Author } from '../../references/Author';

export class Cover extends Work {
  title?: Title;
  author?: Author;
  color: string = '#0f1419';
  accentColor: string = '#1e3a5f';
  visible: boolean = true;
  
  processChildren(children: React.ReactNode): void {
    if (!children) return;
    const items = Array.isArray(children) ? children : [children];
    items.forEach((child: any) => {
      if (child instanceof Title && !this.title) {
        this.title = child;
      } else if (child instanceof Author && !this.author) {
        this.author = child;
      }
    });
  }
  
  componentDidMount(): void {
    setTimeout(() => {
      this.visible = false;
    }, 5000);
  }
  
  bookCoverStyles(): React.CSSProperties {
    const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;
    
    if (isMobile) {
      return {
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100vh',
        background: \`linear-gradient(135deg, \${this.color} 0%, \${this.accentColor} 100%)\`,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        zIndex: 1000,
        transition: 'opacity 1.5s ease-out',
        opacity: this.visible ? 1 : 0,
        pointerEvents: this.visible ? 'all' : 'none'
      };
    }
    
    // Desktop: book-shaped
    return {
      position: 'fixed',
      top: '50%',
      left: '50%',
      transform: 'translate(-50%, -50%)',
      width: '400px',
      height: '600px',
      background: \`linear-gradient(135deg, \${this.color} 0%, \${this.accentColor} 100%)\`,
      borderRadius: '0 10px 10px 0',
      boxShadow: '10px 10px 30px rgba(0,0,0,0.3)',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1000,
      transition: 'opacity 1.5s ease-out, transform 1.5s ease-out',
      opacity: this.visible ? 1 : 0,
      pointerEvents: this.visible ? 'all' : 'none'
    };
  }
  
  component(): React.ReactNode {
    return (
      <div style={this.bookCoverStyles()}>
        <h1 style={this.titleStyles()}>
          {this.title?.text()}
        </h1>
        <div style={this.authorStyles()}>
          by {this.author?.displayName}
        </div>
      </div>
    );
  }
}`}
