                {`${''}export class Book extends Collection<Chapter> {
  cover?: Cover;
  titlePage?: TitlePage;
  tableOfContents?: TableOfContents;
  chapters: Chapter[] = [];
  
  processChildren(children: React.ReactNode): void {
    if (!children) return;
    const items = Array.isArray(children) ? children : [children];
    
    items.forEach((instance: any) => {
      if (!instance) return;
      
      if (instance instanceof Cover && !this.cover) {
        this.cover = instance;
        // Book gets title/author from cover
        this.title = this.cover.title;
        this.author = this.cover.author;
      } else if (instance instanceof TitlePage && !this.titlePage) {
        this.titlePage = instance;
        this.titlePage.container = this;
      } else if (instance instanceof TableOfContents && !this.tableOfContents) {
        this.tableOfContents = instance;
        this.tableOfContents.container = this;
      } else if (instance instanceof Chapter) {
        this.chapters.push(instance);
        instance.container = this;
      }
    });
    
    this.assignChapterNumbers();
  }
  
  assignChapterNumbers(): void {
    this.chapters.forEach((chapter, index) => {
      chapter.number = index + 1;
    });
  }
  
  component(): React.ReactNode {
    return (
      <>
        {this.cover?.component()}
        {!this.cover?.visible && (
          <div className="book-content">
            {this.titlePage?.component()}
            {this.tableOfContents?.component()}
            {this.chapters.map((ch, i) => (
              <div key={ch.id || i}>{ch.component()}</div>
            ))}
          </div>
        )}
      </>
    );
  }
}`}
