                {`${''}import { Section } from './Section';
import { Title } from './Title';
import { Book } from '../collections/books/Book';
import { Next } from '../references/Next';
import { Previous } from '../references/Previous';
import { Up } from '../references/Up';
import { Logo } from '../../base/Logo';

export class Chapter extends Section {
  number?: number;
  title?: Title;
  book?: Book;
  next?: Next;
  previous?: Previous;
  up?: Up;
  
  renderHeader(): React.ReactNode {
    if (!this.book) return null;
    
    const isFirst = this.number === 1;
    const isLast = this.number === this.book.numberOfChapters;
    const hasTableOfContents = !!this.book.tableOfContents;
    
    // Set up navigation
    if (!isFirst) {
      this.previous = new Previous();
      this.previous.target = this.book.chapters[this.number! - 2]; // Previous chapter
    }
    
    if (!isLast) {
      this.next = new Next();
      this.next.target = this.book.chapters[this.number!]; // Next chapter (0-indexed)
    }
    
    // Up goes to book cover/title page
    this.up = new Up();
    this.up.target = this.book.titlePage || this.book.cover;
    
    return (
      <header style={this.headerStyles()}>
        <div style={this.navBarStyles()}>
          <div style={this.leftNavStyles()}>
            {this.renderOrganizationLogo()}
            {!isFirst && this.previous?.component()}
            {hasTableOfContents && this.number! > 1 && this.renderTableOfContentsLink()}
          </div>
          
          <div style={this.centerNavStyles()}>
            <a onClick={() => this.up?.target?.component()} style={this.titleLinkStyles()}>
              {this.book.title?.text()}
            </a>
          </div>
          
          <div style={this.rightNavStyles()}>
            {!isLast && this.next?.component()}
          </div>
        </div>
        
        {this.renderChapterTitle()}
      </header>
    );
  }
  
  renderOrganizationLogo(): React.ReactNode {
    const library = this.book?.container;
    const organization = library?.container;
    
    if (organization && 'logo' in organization) {
      return (
        <div style={{ marginRight: '20px' }}>
          {(organization as any).logo.component()}
        </div>
      );
    }
    return null;
  }
  
  renderTableOfContentsLink(): React.ReactNode {
    return (
      <button 
        onClick={() => {
          // Navigate to table of contents
          window.location.href = '#table-of-contents';
        }}
        style={this.tocButtonStyles()}
        title="Table of Contents"
      >
        ««
      </button>
    );
  }
  
  renderChapterTitle(): React.ReactNode {
    if (!this.title) return null;
    
    return (
      <h1 style={this.chapterTitleStyles()}>
        {this.number && \`Chapter \${this.number}: \`}
        {this.title.text()}
      </h1>
    );
  }
  
  // Style methods
  headerStyles(): React.CSSProperties {
    return {
      padding: '20px 40px',
      borderBottom: '1px solid #e0e0e0',
      background: '#f8f9fa'
    };
  }
  
  navBarStyles(): React.CSSProperties {
    return {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '20px'
    };
  }
  
  leftNavStyles(): React.CSSProperties {
    return {
      display: 'flex',
      alignItems: 'center',
      gap: '10px'
    };
  }
  
  centerNavStyles(): React.CSSProperties {
    return {
      flex: 1,
      textAlign: 'center'
    };
  }
  
  rightNavStyles(): React.CSSProperties {
    return {
      display: 'flex',
      alignItems: 'center',
      gap: '10px'
    };
  }
  
  titleLinkStyles(): React.CSSProperties {
    return {
      fontSize: '1.2em',
      color: '#2c3e50',
      textDecoration: 'none',
      cursor: 'pointer',
      fontWeight: 600,
      transition: 'color 0.2s',
      ':hover': {
        color: '#3498db'
      }
    };
  }
  
  tocButtonStyles(): React.CSSProperties {
    return {
      background: 'none',
      border: '1px solid #ccc',
      borderRadius: '4px',
      padding: '5px 10px',
      cursor: 'pointer',
      fontSize: '14px',
      color: '#666',
      transition: 'all 0.2s',
      ':hover': {
        background: '#f0f0f0',
        borderColor: '#999'
      }
    };
  }
  
  chapterTitleStyles(): React.CSSProperties {
    return {
      margin: '20px 0 0 0',
      fontSize: '2em',
      color: '#333'
    };
  }
  
  component(): React.ReactNode {
    return (
      <article style={this.containerStyles()}>
        {this.renderHeader()}
        
        <main style={this.contentStyles()}>
          {super.content()}
        </main>
        
        <footer style={this.footerStyles()}>
          {this.renderFooter()}
        </footer>
      </article>
    );
  }
}`}
