                {`import { Collection } from '../../../base/Collection';
import { Chapter } from './Chapter';
import { Book } from './Book';
import { Link } from '../../references/Link';

export class TableOfContents extends Collection<Chapter> {
  book?: Book;
  
  tocStyles(): React.CSSProperties {
    return {
      maxWidth: '800px',
      margin: '40px auto',
      padding: '40px 20px',
      minHeight: '100vh'
    };
  }
  
  tocTitleStyles(): React.CSSProperties {
    return {
      fontSize: '2.5em',
      marginBottom: '40px',
      color: '#2c3e50',
      borderBottom: '2px solid #e0e0e0',
      paddingBottom: '20px'
    };
  }
  
  entryStyles(): React.CSSProperties {
    return {
      marginBottom: '30px',
      padding: '20px',
      borderLeft: '3px solid #3498db',
      background: '#f8f9fa',
      transition: 'all 0.3s ease',
      cursor: 'pointer'
    };
  }
  
  entryTitleStyles(): React.CSSProperties {
    return {
      fontSize: '1.5em',
      color: '#2c3e50',
      marginBottom: '10px',
      textDecoration: 'none'
    };
  }
  
  synopsisStyles(): React.CSSProperties {
    return {
      color: '#666',
      fontSize: '0.95em',
      lineHeight: '1.6',
      marginTop: '10px'
    };
  }
  
  chapterNumberStyles(): React.CSSProperties {
    return {
      display: 'inline-block',
      width: '40px',
      height: '40px',
      borderRadius: '50%',
      background: '#3498db',
      color: 'white',
      textAlign: 'center',
      lineHeight: '40px',
      marginRight: '15px',
      fontSize: '1.2em',
      fontWeight: 'bold'
    };
  }
  
  component(): React.ReactNode {
    if (!this.book) return null;
    
    return (
      <nav id="table-of-contents" style={this.tocStyles()}>
        <h1 style={this.tocTitleStyles()}>Table of Contents</h1>
        
        <div>
          {this.book.chapters.map((chapter: Chapter) => {
            const link = new Link();
            link.target = chapter;
            link.text = '';  // We'll render custom content
            
            return (
              <div 
                key={chapter.id || chapter.number} 
                style={this.entryStyles()}
                onClick={() => {
                  // Navigate to chapter
                  if (chapter.component) {
                    window.location.href = \`#chapter-\${chapter.number}\`;
                  }
                }}
              >
                <div style={{ display: 'flex', alignItems: 'flex-start' }}>
                  <span style={this.chapterNumberStyles()}>
                    {chapter.number}
                  </span>
                  
                  <div style={{ flex: 1 }}>
                    <h3 style={this.entryTitleStyles()}>
                      {chapter.title?.text() || \`Chapter \${chapter.number}\`}
                    </h3>
                    
                    {chapter.synopsis && (
                      <p style={this.synopsisStyles()}>
                        {chapter.synopsis}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </nav>
    );
  }
}

const tableOfContents = new TableOfContents();
export default tableOfContents.render();`}
